/* ============================================================
 * FICHIER : src/shared/location/data/guineaLabels.ts
 *
 * Noms à afficher sur la carte : villes (c), localités (t), communes /
 * grands quartiers (s), quartiers (q) et villages (v) de Guinée, avec leurs coordonnées.
 * Sources : nœuds « place » d'OpenStreetMap (© contributeurs OpenStreetMap,
 * ODbL) — dernier champ = 1 — complétés par le référentiel géographique de
 * Shoneya, géocodé une fois (dernier champ = 0).
 * Format : [nom, type, latitude, longitude, vientDOSM]
 * ============================================================ */

export type LabelKind = 'c' | 't' | 's' | 'q' | 'v';

export type GuineaLabel = readonly [name: string, kind: LabelKind, lat: number, lng: number, osm: 0 | 1];

